div.script:
/* ============================================================
   ICON FACTORY
   Every icon is generated fresh per call-site with a unique id
   suffix so gradients never collide across dock/desktop/export.
   ============================================================ */
let __iconSeq = 0;
function uid(){ return 'u' + (__iconSeq++); }

function squircleBase(id, c1, c2){
  return `














    `;
}

const LOGO_LINKMAKER_B64 = "";
const LOGO_EMULATOR_B64 = "";
const LOGO_VOLTAN_B64 = "";

function rasterIcon(id, b64){
  return `










  `;
}

function iconLinkMaker(){
  return rasterIcon(uid(), LOGO_LINKMAKER_B64);
}

function iconEmulator(){
  return rasterIcon(uid(), LOGO_EMULATOR_B64);
}

function iconVoltan(){
  return rasterIcon(uid(), LOGO_VOLTAN_B64);
}

function iconUploader(){
  const id = uid();
  return `
    ${squircleBase(id, '#b9c2cf', '#5b6675')}





  `;
}

function iconBrowser(){
  const id = uid();
  return `
    ${squircleBase(id, '#8b9cff', '#4b35b8')}




  `;
}

const GENERIC_PALETTE = ['#f472b6,#be185d', '#60a5fa,#1d4ed8', '#34d399,#047857', '#fbbf24,#b45309', '#a78bfa,#6d28d9'];
function iconGeneric(letter, seedIndex){
  const id = uid();
  const [c1,c2] = GENERIC_PALETTE[seedIndex % GENERIC_PALETTE.length].split(',');
  return `
    ${squircleBase(id, c1, c2)}
    ${letter}
  `;
}

/* mount icons */
function mountIcon(el, svgHtml){ el.innerHTML = svgHtml; }
mountIcon(document.getElementById('dicon-linkmaker'), iconLinkMaker());
mountIcon(document.getElementById('dicon-browser'), iconBrowser());
mountIcon(document.getElementById('dicon-emulator'), iconEmulator());
mountIcon(document.getElementById('dicon-voltan'), iconVoltan());
document.querySelector('#dock-browser .icon-slot').innerHTML = iconBrowser();
document.querySelector('#dock-linkmaker .icon-slot').innerHTML = iconLinkMaker();
document.querySelector('#dock-emulator .icon-slot').innerHTML = iconEmulator();
document.querySelector('#dock-voltan .icon-slot').innerHTML = iconVoltan();
document.querySelector('#dock-uploader .icon-slot').innerHTML = iconUploader();

/* ============================================================
   APP REGISTRY
   ============================================================ */
const APPS = {
  browser:   { title:'Browser', type:'panel', icon:iconBrowser, render:renderBrowserPanel, w:980, h:680 },
  linkmaker: { title:'Link Maker', type:'iframe', icon:iconLinkMaker, b64:"", w:900, h:660 },
  emulator:  { title:'EmulatorJS', type:'iframe', icon:iconEmulator,  b64:"",  w:960, h:640 },
  voltan:    { title:'Voltan',     type:'iframe', icon:iconVoltan,    b64:"",    w:980, h:660 },
  uploader:  { title:'HTML Uploader', type:'panel', icon:iconUploader, render:renderUploaderPanel, w:640, h:560 },
};

function b64ToUtf8(b64){
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for(let i=0;i bin += String.fromCharCode(b));
  return btoa(bin);
}

/* ============================================================
   WINDOW MANAGER
   ============================================================ */
const layer = document.getElementById('window-layer');
const openWins = {};
let zTop = 10;
let offsetCount = 0;

function focusWindow(win){
  document.querySelectorAll('.window').forEach(w=>w.classList.remove('focused'));
  win.classList.add('focused');
  win.style.zIndex = ++zTop;
  document.getElementById('active-app-label').textContent = win.dataset.title;
}

function openApp(appId){
  if(openWins[appId]){
    const w = openWins[appId];
    w.style.display = 'flex';
    focusWindow(w);
    return;
  }
  const app = APPS[appId];
  if(!app) return;
  const win = document.createElement('div');
  win.className = 'window';
  win.dataset.title = app.title;
  const left = 60 + (offsetCount % 5) * 34;
  const top = 46 + (offsetCount % 5) * 28;
  offsetCount++;
  win.style.left = left + 'px';
  win.style.top = top + 'px';
  win.style.width = app.w + 'px';
  win.style.height = app.h + 'px';

  const titleIcon = app.icon().replace('<svg ', '<svg style="width:15px;height:15px" ');

  win.innerHTML = `




        ${closeGlyph()}
        ${minGlyph()}
        ${zoomGlyph()}


${titleIcon}${app.title}



  `;

  layer.appendChild(win);
  requestAnimationFrame(()=> win.classList.add('open'));

  const body = win.querySelector('.win-body');
  if(app.type === 'iframe'){
    const iframe = document.createElement('iframe');
    iframe.srcdoc = b64ToUtf8(app.b64);
    iframe.sandbox = 'allow-scripts allow-forms allow-same-origin allow-popups allow-modals';
    body.appendChild(iframe);
  } else if(app.type === 'panel'){
    app.render(body);
  }

  const titlebar = win.querySelector('.titlebar');
  let dragging=false, sx=0, sy=0, ox=0, oy=0;
  titlebar.addEventListener('mousedown', (e)=>{
    if(e.target.closest('button')) return;
    dragging = true; sx=e.clientX; sy=e.clientY;
    ox = win.offsetLeft; oy = win.offsetTop;
    focusWindow(win);
    e.preventDefault();
  });
  window.addEventListener('mousemove',(e)=>{
    if(!dragging) return;
    win.style.left = Math.max(0, ox + (e.clientX-sx)) + 'px';
    win.style.top = Math.max(26, oy + (e.clientY-sy)) + 'px';
  });
  window.addEventListener('mouseup',()=> dragging=false);

  win.addEventListener('mousedown', ()=> focusWindow(win));

  win.querySelector('.close').addEventListener('click', ()=> closeApp(appId));
  win.querySelector('.min').addEventListener('click', ()=>{
    win.style.display='none';
    dockItem(appId)?.classList.remove('running');
  });
  win.querySelector('.zoom').addEventListener('click', ()=>{
    if(win.dataset.zoomed==='1'){
      win.style.width = app.w+'px'; win.style.height = app.h+'px';
      win.style.left = left+'px'; win.style.top = top+'px';
      win.dataset.zoomed = '0';
    } else {
      win.style.width = 'calc(100vw - 24px)';
      win.style.height = 'calc(100vh - 26px - 24px)';
      win.style.left = '12px'; win.style.top = '34px';
      win.dataset.zoomed = '1';
    }
  });

  openWins[appId] = win;
  dockItem(appId)?.classList.add('running');
  focusWindow(win);
}

function closeApp(appId){
  const win = openWins[appId];
  if(!win) return;
  win.classList.add('closing');
  win.classList.remove('open');
  setTimeout(()=>{ win.remove(); }, 180);
  delete openWins[appId];
  dockItem(appId)?.classList.remove('running');
}

function dockItem(appId){ return document.getElementById('dock-'+appId); }

function closeGlyph(){ return ``; }
function minGlyph(){ return ``; }
function zoomGlyph(){ return ``; }

document.querySelectorAll('.dicon[data-app], .dock-item[data-app]').forEach(el=>{
  el.addEventListener('click', ()=> openApp(el.dataset.app));
  el.addEventListener('dblclick', ()=> openApp(el.dataset.app));
});

/* ============================================================
   HTML UPLOADER  (session-only — kept in memory, not persisted)
   ============================================================ */
let uploadCounter = 0;

function renderUploaderPanel(container){
  container.innerHTML = `



HTML Uploader

Add your own .html file as a new app icon on the desktop. It runs entirely in your browser, sandboxed inside its own window — nothing is uploaded anywhere.




Drop an .html file here, or click to choose

Added apps live only for this session





Uploaded apps are kept in memory for this browser tab only — reloading the page clears them, since this page intentionally avoids writing to your browser's storage.

  `;
  const dz = container.querySelector('#dz');
  const input = container.querySelector('#fileInput');
  const list = container.querySelector('#uploadedList');

  dz.addEventListener('click', ()=> input.click());
  dz.addEventListener('dragover', (e)=>{ e.preventDefault(); dz.classList.add('hover'); });
  dz.addEventListener('dragleave', ()=> dz.classList.remove('hover'));
  dz.addEventListener('drop', (e)=>{
    e.preventDefault(); dz.classList.remove('hover');
    if(e.dataTransfer.files.length) handleFile(e.dataTransfer.files[0]);
  });
  input.addEventListener('change', ()=>{
    if(input.files.length) handleFile(input.files[0]);
    input.value = '';
  });

  function handleFile(file){
    if(!/\.html?$/i.test(file.name)){
      alert('Please choose an .html file.');
      return;
    }
    const reader = new FileReader();
    reader.onload = ()=>{
      const text = reader.result;
      registerUploadedApp(file.name, text);
      refreshList();
    };
    reader.readAsText(file);
  }

  function refreshList(){
    list.innerHTML = '';
    Object.keys(APPS).filter(k=>APPS[k].isUpload).forEach(id=>{
      const app = APPS[id];
      const row = document.createElement('div');
      row.className = 'uploaded-row';
      row.innerHTML = `${app.icon()}${app.title}Open`;
      list.appendChild(row);
    });
    list.querySelectorAll('button[data-open]').forEach(btn=>{
      btn.addEventListener('click', ()=> openApp(btn.dataset.open));
    });
  }
  refreshList();
}

function registerUploadedApp(filename, htmlText){
  uploadCounter++;
  const id = 'upload_' + uploadCounter;
  const title = filename.replace(/\.html?$/i,'');
  const letter = title.trim().charAt(0).toUpperCase() || '?';
  const seedIndex = uploadCounter;
  const iconFn = ()=> iconGeneric(letter, seedIndex);

  APPS[id] = {
    title: title.length > 22 ? title.slice(0,22)+'…' : title,
    type: 'iframe',
    icon: iconFn,
    b64: utf8ToB64(htmlText),
    w: 900, h: 640,
    isUpload: true
  };

  // add a desktop icon for it
  const dIcons = document.getElementById('desktop-icons');
  const el = document.createElement('div');
  el.className = 'dicon';
  el.dataset.app = id;
  el.innerHTML = `
${iconFn()}${APPS[id].title}`;
  el.addEventListener('click', ()=> openApp(id));
  el.addEventListener('dblclick', ()=> openApp(id));
  dIcons.prepend(el);

  openApp(id);
}

/* ============================================================
   BROWSER
   Browserless-backed browsing:
   - /content renders full pages in a managed browser
   - Google, Bing, and DuckDuckGo search pages are rendered through it
   - the Read button extracts text from the Browserless response
   The token is kept in sessionStorage for this tab only.
   ============================================================ */
function browserEsc(value){
  return String(value == null ? '' : value)
    .replace(/&/g,'&').replace(//g,'>')
    .replace(/"/g,'"').replace(/'/g,''');
}

function browserUrl(value){
  let url = String(value || '').trim();
  if(!url) return '';
  if(!/^https?:\/\//i.test(url)) url = 'https://' + url;
  try{
    const parsed = new URL(url);
    return /^https?:$/.test(parsed.protocol) ? parsed.href : '';
  }catch(e){ return ''; }
}

function renderBrowserPanel(container){
  container.innerHTML = `




New tab


        ‹
        ›
        ⌂

        Go
        Read
        ↗


Browserless API token required.





Browse the web

Browserless renders pages server-side, then returns the rendered HTML to this Workbench window. Add your Browserless API token below to enable the API.


            Browserless API token required

Paste your Browserless API token. This uses the current REST /chromium/content endpoint (with /content compatibility). The token stays in this browser tab.

You opened this file directly from file://. Browser security can block API requests from a local file. Hosting this HTML on Vercel/GitHub Pages fixes that.



              Test & Enable

            Open Browserless ↗




            Search


Browserless Search API

Free tools included



MDN Web DocsReliable, free web platform documentation.

WikipediaOpen reference content with a public API.

Example siteA safe page for testing direct browsing.









  `;

  const address = container.querySelector('#browserAddress');
  const homeQuery = container.querySelector('#browserHomeQuery');
  const home = container.querySelector('#browserHome');
  const frame = container.querySelector('#browserFrame');
  const reader = container.querySelector('#browserReader');
  const status = container.querySelector('#browserStatus');
  const tab = container.querySelector('#browserTab');
  const results = container.querySelector('#browserResults');
  const readBtn = container.querySelector('#browserRead');
  let currentUrl = '';
  let history = [];
  const tokenKey = 'workbench_browserless_token';
  const setup = container.querySelector('#browserSetup');
  const tokenInput = container.querySelector('#browserToken');
  const saveToken = container.querySelector('#saveBrowserToken');
  const originWarning = container.querySelector('#browserOriginWarning');
  if(location.protocol === 'file:') originWarning.style.display = 'block';

  function getToken(){
    try{ return sessionStorage.getItem(tokenKey) || ''; }catch(e){ return ''; }
  }
  function setToken(value){
    try{ sessionStorage.setItem(tokenKey, value.trim()); }catch(e){}
  }
  function hasToken(){
    if(!getToken()){
      setup.style.display = 'block';
      setStatus('Add a Browserless API token before using the browser.');
      return false;
    }
    setup.style.display = 'none';
    return true;
  }
  function browserlessUrl(path){
    const cleanPath = String(path || '').replace(/^\/+/, '');
    return 'https://production-sfo.browserless.io/' + cleanPath + '?token=' + encodeURIComponent(getToken());
  }

  async function browserlessFetch(path, payload){
    const token = getToken();
    if(!token) throw new Error('No Browserless API token saved.');
    if(location.protocol === 'file:'){
      throw new Error('This page is opened with file://. Host it on Netlify/Vercel/GitHub Pages first.');
    }
    const controller = new AbortController();
    const timer = setTimeout(()=>controller.abort(), 60000);
    try{
      // Browserless REST API: POST /content?token=...
      // Keep the endpoint simple and documented instead of trying undocumented paths.
      const response = await fetch(browserlessUrl(path), {
        method:'POST',
        cache:'no-store',
        headers:{
          'Content-Type':'application/json',
          'Cache-Control':'no-cache'
        },
        body:JSON.stringify(payload),
        signal:controller.signal
      });
      if(response.ok) return response;
      let detail = '';
      try{ detail = (await response.text()).slice(0,700); }catch(e){}
      let message = 'HTTP ' + response.status;
      if(response.status === 401) message += ' — invalid or expired Browserless token.';
      else if(response.status === 403) message += ' — request rejected by Browserless.';
      else if(response.status === 429) message += ' — Browserless rate/usage limit reached.';
      if(detail) message += ' — ' + detail.replace(/\s+/g,' ').trim();
      throw new Error(message);
    }catch(err){
      if(err && err.name === 'AbortError') throw new Error('Request timed out after 60 seconds.');
      if(err instanceof TypeError) throw new Error('Network/CORS request failed. Make sure this is hosted on HTTPS and the Browserless service is reachable.');
      throw err;
    }finally{ clearTimeout(timer); }
  }
  function searchUrl(query){
    return 'https://www.google.com/search?q=' + encodeURIComponent(query);
  }
  async function searchWithApi(query){
    // Do not depend on Browserless /search: Browserless documents that endpoint
    // as Cloud-plan-only. Instead, render a normal search page through /content.
    const q = String(query || '').trim();
    const searchPage = 'https://www.google.com/search?q=' + encodeURIComponent(q);
    const response = await browserlessFetch('content', {
      url:searchPage,
      gotoOptions:{waitUntil:'domcontentloaded', timeout:30000},
      waitForTimeout:1500,
      bestAttempt:true
    });
    const html = await response.text();
    const doc = new DOMParser().parseFromString(html, 'text/html');
    const items = [];
    doc.querySelectorAll('a').forEach(a=>{
      const href = a.href || a.getAttribute('href') || '';
      const text = (a.innerText || a.textContent || '').trim().replace(/\s+/g,' ');
      if(!text || !href || !/^https?:/i.test(href)) return;
      if(/google\.(com|co\.)|accounts\.google|support\.google/i.test(href)) return;
      const host = (()=>{try{return new URL(href).hostname}catch(e){return ''}})();
      if(!host) return;
      if(items.some(x=>x.url===href)) return;
      items.push({title:text.slice(0,180), url:href, text:''});
    });
    return items.slice(0,8);
  }

  saveToken.addEventListener('click', async ()=>{
    const value = tokenInput.value.trim();
    if(!value){ setStatus('Paste a Browserless API token first.'); return; }
    setToken(value);
    setStatus('Testing Browserless API…');
    saveToken.disabled = true;
    try{
      await browserlessFetch('content', {url:'https://example.com/', bestAttempt:true});
      tokenInput.value = '';
      setup.style.display = 'none';
      setStatus('API connected successfully.');
      showFrame('https://www.google.com/');
    }catch(err){
      if(/HTTP (401|403)/.test(err.message)) { try{ sessionStorage.removeItem(tokenKey); }catch(e){} }
      setStatus('API test failed: ' + err.message);
      setup.style.display = 'block';
    }finally{ saveToken.disabled = false; }
  });
  if(getToken()) {
    setup.style.display = 'none';
    setStatus('Saved Browserless token found. Click Go/Search to test the API.');
  }

  function setStatus(text){ status.textContent = text; }
  function showHome(){
    home.style.display = 'block';
    frame.style.display = 'none';
    reader.style.display = 'none';
    tab.textContent = 'New tab';
  }
  async function showFrame(url){
    const clean = browserUrl(url);
    if(!clean || !hasToken()) return;
    currentUrl = clean;
    address.value = clean;
    homeQuery.value = clean;
    home.style.display = 'none';
    reader.style.display = 'none';
    frame.style.display = 'block';
    frame.srcdoc = '
Loading through Browserless…';
    tab.textContent = new URL(clean).hostname;
    setStatus('Rendering ' + clean + ' through Browserless…');
    try{
      const response = await browserlessFetch('content', {url:clean, gotoOptions:{waitUntil:'domcontentloaded', timeout:30000}, bestAttempt:true});
      const html = await response.text();
      const base = '';
      if(/
]*>/i.test(html)) frame.srcdoc = html.replace(/
]*)>/i, '
' + base);
      else frame.srcdoc = '
' + base + '' + html + '';
      setStatus('API connected — page loaded through Browserless.');
    }catch(err){
      frame.srcdoc = '
Browserless could not load this page (' + browserEsc(err.message) + '). Check your token or click ↗ to open it externally.';
      setStatus('Browserless request failed.');
    }
  }
  function showReader(url, text){
    currentUrl = url;
    address.value = url;
    home.style.display = 'none';
    frame.style.display = 'none';
    reader.style.display = 'block';
    reader.innerHTML = '
Readable page
' + browserEsc(url) + '';
    reader.appendChild(document.createTextNode(text));
    tab.textContent = 'Reader · ' + new URL(url).hostname;
  }
  function addHistory(url){
    if(!url) return;
    if(history[history.length-1] !== url) history.push(url);
  }
  async function readPage(url){
    const clean = browserUrl(url);
    if(!clean || !hasToken()){ setStatus('Enter a valid URL and add a Browserless token first.'); return; }
    readBtn.disabled = true;
    setStatus('Reading through Browserless…');
    try{
      const response = await browserlessFetch('content', {url:clean, gotoOptions:{waitUntil:'domcontentloaded', timeout:30000}, bestAttempt:true});
      const html = await response.text();
      const parsed = new DOMParser().parseFromString(html, 'text/html');
      parsed.querySelectorAll('script,style,noscript,svg').forEach(node=>node.remove());
      const text = (parsed.body ? parsed.body.innerText : parsed.documentElement.innerText || '').replace(/\n{3,}/g,'\n\n').trim();
      showReader(clean, text);
      setStatus('API connected — readable text loaded through Browserless.');
    }catch(err){
      setStatus('Browserless reader failed (' + err.message + '). Check your token.');
    }finally{ readBtn.disabled = false; }
  }
  function renderResults(items, heading){
    results.innerHTML = '
' + browserEsc(heading) + '';
    if(!items.length){
      results.innerHTML += '
No results came back from this free endpoint. Try a more specific phrase.';
      return;
    }
    items.slice(0,8).forEach(item=>{
      const row = document.createElement('div');
      row.className = 'browser-result';
      row.innerHTML = '' + browserEsc(item.title || item.url) + '' +
        '
' + browserEsc(item.url) + '
' + browserEsc(item.text || '') + '';
      results.appendChild(row);
    });
    results.querySelectorAll('a[data-url]').forEach(link=>{
      link.addEventListener('click', ()=>{
        const url = browserUrl(link.dataset.url);
        if(url){ addHistory(url); showFrame(url); }
      });
    });
  }
  async function searchWeb(query){
    const q = String(query || '').trim();
    if(!q) return;
    const urlCandidate = browserUrl(q);
    if(/^(https?:\/\/|www\.)/i.test(q) || (urlCandidate && q.includes('.'))){
      addHistory(urlCandidate); showFrame(urlCandidate); return;
    }
    if(!hasToken()) return;
    address.value = q;
    homeQuery.value = q;
    home.style.display = 'block';
    frame.style.display = 'none';
    reader.style.display = 'none';
    results.innerHTML = '
Searching with Browserless…';
    try{
      const items = await searchWithApi(q);
      renderResults(items, 'Search results');
      setStatus('API connected — search results loaded from Browserless.');
    }catch(err){
      results.innerHTML = '';
      setStatus('Search API failed (' + err.message + '). Opening Google through Browserless instead…');
      await showFrame(searchUrl(q));
    }
  }
  container.querySelector('#browserGo').addEventListener('click', ()=> searchWeb(address.value));
  address.addEventListener('keydown', e=>{ if(e.key === 'Enter') searchWeb(address.value); });
  container.querySelector('#browserSearch').addEventListener('click', ()=> searchWeb(homeQuery.value));
  homeQuery.addEventListener('keydown', e=>{ if(e.key === 'Enter') searchWeb(homeQuery.value); });
  container.querySelector('#browserHomeBtn').addEventListener('click', showHome);
  readBtn.addEventListener('click', ()=> readPage(currentUrl || address.value));
  container.querySelector('#browserExternal').addEventListener('click', ()=>{
    if(!hasToken()) return;
    const url = browserUrl(currentUrl || address.value);
    if(url) window.open(url, '_blank', 'noopener,noreferrer');
  });
  container.querySelectorAll('.browser-link-card[data-url]').forEach(card=>{
    card.addEventListener('click', ()=>{ addHistory(card.dataset.url); showFrame(card.dataset.url); });
  });
}

/* ============ CLOCK ============ */
function tick(){
  const d = new Date();
  const opts = {weekday:'short', month:'short', day:'numeric'};
  const dateStr = d.toLocaleDateString('en-US', opts);
  let h = d.getHours(); const m = d.getMinutes();
  const ampm = h>=12?'PM':'AM'; h = h%12; if(h===0) h=12;
  const mm = m<10?'0'+m:m;
  document.getElementById('clock').textContent = `${dateStr}  ${h}:${mm} ${ampm}`;
}
tick(); setInterval(tick, 1000*15);

document.querySelector('.desktop').addEventListener('click', (e)=>{
  if(e.target.closest('.dicon')) return;
  document.getElementById('active-app-label').textContent = 'Finder';
  document.querySelectorAll('.window').forEach(w=>w.classList.remove('focused'));
});
